'use strict';
const ICONS={leaf:'M20 3C11 2 3 6 4 13c1 8 14 10 16-10ZM4 21 15 10',camera:'M3 6h5l2-3h4l2 3h5v15H3zM16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',plus:'M12 5v14M5 12h14',sparkles:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z',lock:'M5 10h14v12H5zM8 10V6a4 4 0 0 1 8 0v4',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',search:'m21 21-4.5-4.5M19 10.5A8.5 8.5 0 1 1 2 10.5a8.5 8.5 0 0 1 17 0',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',box:'m21 8-9 5-9-5M3 8l9-5 9 5v10l-9 5-9-5zM12 13v10',book:'M3 3h6a4 4 0 0 1 4 4v14a4 4 0 0 0-4-2H3zM13 7a4 4 0 0 1 4-4h5v16h-5a4 4 0 0 0-4 2',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',group:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',refresh:'M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-1l2 3M4 15l2 3a7 7 0 0 0 12-1',file:'M14 2H4v20h16V8zM14 2v6h6M8 13h8M8 17h6',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6zM8 12l3 3 5-6'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[n]||ICONS.box}"/></svg>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',minimumFractionDigits:0,maximumFractionDigits:2}).format(Number(x));
const price=x=>x===null||x===undefined||x===''?'Ask for price':Number(x)===0?'Free':money(x);
const CATEGORIES=['Furniture','Electronics','Home & living','Kitchen','Fashion','Books','Sports & outdoors','Toys & games','Tools','Other'];
const CONDITIONS=['Not specified','Like new','Gently used','Well loved','Needs repair'];
const MAX_PHOTOS=40,MAX_PER_ITEM=8;
let state={version:1,catalogue:{title:'A little room for what’s next.',ownerName:'',description:'Good things, ready for another beginning.'},photos:[],items:[]};
let view='space',query='',category='All categories',reviewFilter='all',selected=new Set(),busy=false,aiController=null,analysisError='',aiMessage='',aiStage='',aiProgress=0,editingId=null,editingCover=null,toastTimer,saveTimer,dbPromise,saveLabel='Saved on this device',snapshot=false,lastShareUrl='';
const uid=()=>crypto.randomUUID();
const byPhoto=id=>state.photos.find(p=>p.id===id);
const byItem=id=>state.items.find(p=>p.id===id);
const approvedItems=()=>state.items.filter(p=>p.approved===true&&p.status!=='draft');
function coverPhoto(item){return byPhoto(item.thumbnailId)||byPhoto(item.photoIds?.[0]);}
function exportItems(){return state.items.map(p=>{const ordered=[p.thumbnailId,...(p.photoIds||[]).filter(id=>id!==p.thumbnailId)].filter(Boolean);const photos=ordered.map(byPhoto).filter(Boolean);return {...p,image:photos[0]?.dataUrl||'',images:photos.map(x=>x.dataUrl),photos:photos.map(x=>({id:x.id,dataUrl:x.dataUrl,width:x.width,height:x.height,quality:x.quality})),thumbnailId:photos[0]?.id};});}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),5000);}
function db(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open('let-it-go-local',1);r.onupgradeneeded=()=>r.result.createObjectStore('projects');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(new Error('Browser storage is unavailable. Use a project backup to keep your work.'));});return dbPromise;}
async function saveProject(){if(snapshot)return;try{const database=await db();await new Promise((resolve,reject)=>{const t=database.transaction('projects','readwrite');t.objectStore('projects').put(state,'workspace');t.oncomplete=resolve;t.onerror=reject;t.onabort=reject;});saveLabel='Saved on this device';}catch{saveLabel='Not saved — download a project backup';toast('Browser storage could not save this collection. Download a project backup before leaving.');}updateSaveLabel();}
function scheduleSave(){if(snapshot)return;lastShareUrl='';saveLabel='Saving on this device…';updateSaveLabel();clearTimeout(saveTimer);saveTimer=setTimeout(saveProject,500);}
function updateSaveLabel(){document.querySelectorAll('[data-save-label]').forEach(el=>el.textContent=snapshot?'Shared catalogue snapshot':saveLabel);}
async function initialise(){try{const params=new URLSearchParams(location.search);if(params.has('manage')){snapshot=true;view='help';render();ownerManagement(params.get('manage'),new URLSearchParams(location.hash.slice(1)).get('token'));return;}if(params.has('catalogue')){const data=await window.LetItGoHosted.read(params.get('catalogue'));loadHosted(data);snapshot=true;view='catalogue';lastShareUrl=location.href;render();return;}if(location.hash.startsWith('#catalogue=')){const data=await window.LetItGoShare.decodeLink(location.hash);loadImported(data);snapshot=true;view='catalogue';lastShareUrl=location.href;render();return;}const database=await db();const existing=await new Promise((resolve,reject)=>{const r=database.transaction('projects').objectStore('projects').get('workspace');r.onsuccess=()=>resolve(r.result);r.onerror=reject;});if(existing?.version===1&&Array.isArray(existing.items)&&Array.isArray(existing.photos)){state=existing;}}catch(error){saveLabel='Use a backup to keep your work';analysisError=error.message;if(location.hash.startsWith('#catalogue=')||new URLSearchParams(location.search).has('catalogue')){snapshot=true;view='catalogue';}}render();if(snapshot&&analysisError)toast('This shared link could not be opened: '+analysisError);}
function footer(){return `<footer class="footer"><span><strong>Let It Go!</strong> A little less stuff. A little more space.</span><span>${snapshot?'Shared snapshot · availability may change':'No account. No cloud photo uploads.'} · <button data-action="view" data-view="help">How it works</button></span></footer>`;}
function header(){return `<header class="topbar"><button class="logo" data-action="view" data-view="${snapshot?'catalogue':'space'}"><img src="icon.svg" alt="">Let It Go!</button><nav aria-label="Main navigation">${snapshot?'':`<button class="${view==='space'?'active':''}" data-action="view" data-view="space">Your space</button>`}<button class="${view==='catalogue'?'active':''}" data-action="view" data-view="catalogue">Catalogue</button><button class="${view==='help'?'active':''}" data-action="view" data-view="help">How it works</button></nav><span class="device-badge">${icon('lock')}<span data-save-label>${esc(snapshot?'Shared catalogue snapshot':saveLabel)}</span></span>${snapshot?'<a class="secondary" href="'+esc(location.pathname)+'">Create your own</a>':'<button class="secondary" data-action="share">'+icon('link')+'Share catalogue</button>'}</header>`;}
function intro(){return `<section class="intro"><div><div class="eyebrow">${icon('leaf')}Make room for what comes next</div><h1>Clutter this space.<br><em>Let the rest go.</em></h1><p class="lead">With the items you’re ready to declutter.<br>Drop your photos. We’ll help you sort them into items, pick a cover, and make a catalogue worth sharing.</p><div class="intro-features"><span>${icon('check')}No sign-up</span><span>${icon('sparkles')}Browser-based AI</span><span>${icon('book')}PDFs to pass around</span></div></div><div class="intro-art" aria-label="Illustration of three sample item photos"><div class="art-circle"></div><div class="art-circle small"></div><span class="art-title">A few things. A fresh beginning.</span><div class="art-photo one"><div class="atlas sprite-0"></div><small>A reading corner favourite</small></div><div class="art-photo two"><div class="atlas sprite-1"></div><small>Ready for its next playlist</small></div><div class="art-photo three"><div class="atlas sprite-2"></div><small>A little light, rehomed</small></div><div class="art-label">Illustrative sample items</div></div></section>`;}
function uploader(){return `<section class="dropzone" id="dropzone"><span class="drop-icon">${icon('camera')}</span><div class="drop-copy"><h2>Drop all the photos here.</h2><p>Different items. Different angles. One place to start.</p><small>Up to ${MAX_PHOTOS} JPG, PNG or WebP photos · 15 MB each</small></div><label class="primary">${icon('plus')}Choose photos<input class="visually-hidden" id="photo-input" type="file" multiple accept="image/jpeg,image/png,image/webp" ${busy?'disabled':''}></label></section><div class="local-note">${icon('lock')}<span>Photos stay in this browser until you choose to export or share. The AI model downloads about 154 MB on first use.</span></div>`;}
function progressPanel(){if(!busy&&!analysisError&&!state.photos.length)return '';const remaining=state.items.filter(p=>!p.approved).length;return `<section class="status-panel"><span class="status-icon">${icon(busy?'sparkles':analysisError?'refresh':'check')}</span><div class="status-text"><strong id="ai-status-title">${esc(busy?aiMessage||'Getting your photos ready…':analysisError?'AI sorting needs another try.':`${state.photos.length} photos. ${state.items.length} suggested ${state.items.length===1?'item':'items'}. You have the final say.`)}</strong><small id="ai-status-detail">${esc(busy?'Keep this tab open while the browser works.':analysisError||`${remaining} ${remaining===1?'item needs':'items need'} review. Similar items can be mixed up, so check every group.`)}</small>${busy?`<div class="progress-track"><span id="ai-progress" style="width:${aiProgress}%"></span></div>`:''}</div>${busy?'<button class="text-button" data-action="cancel-ai">Stop</button>':`<button class="secondary" data-action="sort">${icon('sparkles')}${analysisError?'Retry AI':'Sort with AI'}</button>`}</section>`;}
function filterItems(){let result=state.items.filter(p=>view==='catalogue'||snapshot?p.approved&&p.status!=='draft':true);if(category!=='All categories')result=result.filter(p=>p.category===category);if(query)result=result.filter(p=>[p.title,p.brand,p.model,p.description,p.category].join(' ').toLowerCase().includes(query.toLowerCase()));if(view==='space'&&!snapshot&&reviewFilter==='pending')result=result.filter(p=>!p.approved);if(view==='space'&&!snapshot&&reviewFilter==='confirmed')result=result.filter(p=>p.approved);return result;}
function itemCard(item){const cover=coverPhoto(item);return `<article class="item-card"><div class="card-photo">${view==='space'&&!snapshot?`<input class="select-item" type="checkbox" data-select="${item.id}" ${selected.has(item.id)?'checked':''} aria-label="Select ${esc(item.title||'item')}" ${busy?'disabled':''}>`:''}<button class="image-open" data-action="${view==='catalogue'||snapshot?'details':'review'}" data-id="${item.id}" aria-label="${view==='catalogue'?'View':'Review'} ${esc(item.title)}"><img src="${esc(cover?.dataUrl||'')}" alt="${esc(item.title||'Item photo')}" loading="lazy"></button><span class="review-tag ${item.approved?'confirmed':''}">${item.approved?'Confirmed':'Needs review'}</span><span class="photo-count">${item.photoIds.length} ${item.photoIds.length===1?'photo':'photos'}</span></div><div class="card-category">${esc(item.category||'Other')}</div><h3>${esc(item.title||'Item to identify')}</h3><div class="card-price">${price(item.price)}</div><div class="card-source">${icon(item.aiSuggested?'sparkles':'camera')}${item.aiSuggested?'AI suggestion · owner review required':'Owner-provided details'}</div>${view==='space'&&!snapshot?`<div class="card-actions"><button class="text-button" data-action="review" data-id="${item.id}" ${busy?'disabled':''}>${item.approved?'Edit details':'Review item'}</button>${item.photoIds.length>1?`<button class="text-button" data-action="split" data-id="${item.id}" ${busy?'disabled':''}>Separate</button>`:''}</div>`:`<div class="card-source">${esc(item.status==='sold'?'Rehomed':item.status==='reserved'?'Reserved':item.condition||'Condition not specified')}</div>`}</article>`;}
function workspace(){const shown=filterItems();return `${intro()}${uploader()}${progressPanel()}<div class="workspace-head"><div><h2>Your sorting space</h2><p>${state.items.length} items · ${approvedItems().length} confirmed · ${state.photos.length} photos</p></div><div class="toolbar-actions"><button class="secondary" data-action="import">${icon('upload')}Open backup</button><button class="secondary" data-action="backup" ${!state.items.length?'disabled':''}>${icon('file')}Save backup</button><button class="primary" data-action="view" data-view="catalogue" ${!approvedItems().length?'disabled':''}>${icon('book')}Preview catalogue</button></div></div>${state.items.length?`<div class="workspace-tools"><label class="search">${icon('search')}<input id="search" type="search" value="${esc(query)}" placeholder="Find an item…" aria-label="Search items"></label>${categoryFilter()}<select class="status-select" id="review-filter" aria-label="Review status"><option value="all"${reviewFilter==='all'?' selected':''}>All items</option><option value="pending"${reviewFilter==='pending'?' selected':''}>Needs review</option><option value="confirmed"${reviewFilter==='confirmed'?' selected':''}>Confirmed</option></select><div class="selection-tools"><button class="secondary" data-action="merge" ${selected.size<2||busy?'disabled':''}>${icon('group')}Group selected</button><button class="secondary" data-action="remove-selected" ${!selected.size||busy?'disabled':''}>Remove</button></div></div>`:''}${shown.length?`<div class="item-grid">${shown.map(itemCard).join('')}</div>`:`<div class="empty-panel"><h3>${state.items.length?'A quiet corner.':'A little less stuff starts here.'}</h3><p>${state.items.length?'Try a different search or category.':'Add a whole batch. AI will suggest which photos belong together, what the items are, and which photo makes the best cover.'}</p>${!state.items.length?'<button class="text-button sample-button" data-action="sample">Try a few sample photos</button>':''}</div>`}<input type="file" id="project-input" class="visually-hidden" accept="application/json,.json">`;}
function categoryFilter(){return `<select class="category-select" id="category" aria-label="Product category"><option>All categories</option>${CATEGORIES.map(c=>`<option${category===c?' selected':''}>${c}</option>`).join('')}</select>`;}
function cataloguePage(){const shown=filterItems();return `<section class="catalogue-top"><div><div class="eyebrow">${icon('leaf')}A Let It Go! catalogue</div><h1>${esc(state.catalogue.title)}</h1><p>${esc(state.catalogue.description)}</p>${state.catalogue.ownerName?`<small>Put together by ${esc(state.catalogue.ownerName)}</small>`:''}</div><div class="toolbar-actions">${!snapshot?'<button class="secondary" data-action="catalogue-settings">Edit introduction</button>':''}<button class="primary" data-action="share" ${!approvedItems().length?'disabled':''}>${icon('download')}Export & share</button></div></section><div class="workspace-head"><div><h2>Ready for another beginning.</h2><p>${shown.length} confirmed ${shown.length===1?'item':'items'} · ${snapshot?'A shared snapshot; check current availability with the owner.':'Private and unconfirmed items are hidden.'}</p></div>${snapshot?'':'<button class="text-button" data-action="view" data-view="space">Back to your space</button>'}</div><div class="workspace-tools"><label class="search">${icon('search')}<input id="search" type="search" value="${esc(query)}" placeholder="Find something…" aria-label="Search catalogue"></label>${categoryFilter()}</div>${shown.length?`<div class="item-grid">${shown.map(itemCard).join('')}</div>`:`<div class="empty-panel"><h3>Your catalogue is taking shape.</h3><p>Confirm item details in your sorting space to include them here.</p>${!snapshot?'<button class="primary" data-action="view" data-view="space">Review your items</button>':''}</div>`}`;}
function helpPage(){return `<div class="eyebrow">A few things to know</div><h1 class="section-heading">You bring the clutter.<br>We’ll help you sort.</h1><p class="muted">A simple browser tool. No account, no subscription, no API key.</p><div class="help-grid"><section class="panel"><h2>Photos become suggestions.</h2><p>A default CLIP model runs on your device. It compares photos with product labels and with one another to suggest categories and product groups. A quality score helps pick a cover photo from each group.</p><p>Similar products can be grouped incorrectly, and different angles of one item may stay separate. Review every group; merge or separate them as needed. A scene with several products needs your attention.</p></section><section class="panel"><h2>Your final say.</h2><p>Confirm the item name, category, photos and cover. Add your own price, brand, model, condition, age and product reference. A photo alone does not establish the age, authenticity or hidden condition of an item.</p><p>Only items you explicitly confirm are included in your catalogue, PDF or shared HTML.</p></section><section class="panel"><h2>Local first.</h2><p>Photos are processed in the browser and saved in this device’s browser storage. Model code and weights download from jsDelivr and Hugging Face, about154MB of model weights the first time. Internet access is needed for the initial download.</p><p>Save a project backup to move work between devices or protect it from browser-data clearing. Shared catalogue files and links contain the photos you include.</p></section><section class="panel"><h2>Share without a server.</h2><p>A PDF is ready to send in your preferred app. A downloadable HTML catalogue includes its photos, filters and galleries and can be viewed offline.</p><p>Small catalogues can fit inside a self-contained link. Larger photo collections usually exceed practical link lengths. A short, updateable link for those requires a storage service; GitHub Pages alone does not provide one. Exported snapshots cannot be recalled or updated remotely.</p></section><section class="panel"><h2>If AI will not load.</h2><p>Your browser needs enough memory for the model. Slow networks, blocked model hosts and some devices may prevent loading. You can retry or use the same grouping and review tools manually. The app never labels a manual fallback as AI.</p></section><section class="panel"><h2>Keep this a personal tool.</h2><p>This package is prepared for GitHub Pages with relative asset paths. There is no server, login or billing code. If you later make this a commercial service, choose hosting and storage suited to that use.</p></section></div>`;}
function render(){document.getElementById('app').innerHTML=header()+`<main class="page" id="main" tabindex="-1">${view==='help'?helpPage():view==='catalogue'?cataloguePage():workspace()}${footer()}</main>`;bindPage();}
function bindPage(){const input=document.getElementById('photo-input');if(input)input.onchange=e=>addPhotos([...e.target.files]);const drop=document.getElementById('dropzone');if(drop){drop.ondragover=e=>{e.preventDefault();if(!busy)drop.classList.add('dragging');};drop.ondragleave=()=>drop.classList.remove('dragging');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragging');if(!busy)addPhotos([...e.dataTransfer.files]);};}const backup=document.getElementById('project-input');if(backup)backup.onchange=e=>importProject(e.target.files?.[0]);}
function modal(title,html,narrow=false){document.getElementById('modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${narrow?'narrow':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="modal-header"><h2>${esc(title)}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></header><div class="modal-body">${html}</div></section></div>`;document.body.style.overflow='hidden';setTimeout(()=>document.querySelector('.modal input,.modal button')?.focus(),15);}
function closeModal(){window.LetItGoHosted?.reset();document.getElementById('modal-root').innerHTML='';document.body.style.overflow='';editingId=null;editingCover=null;}
function blankItem(ids,extra={}){return {id:uid(),photoIds:ids,thumbnailId:ids[0],title:'Item to identify',category:'Other',brand:'',model:'',condition:'Not specified',age:'',productUrl:'',description:'',price:null,status:'available',approved:false,aiSuggested:false,...extra};}
function imageQuality(image,canvas){const width=image.naturalWidth||image.width,height=image.naturalHeight||image.height;const ctx=canvas.getContext('2d',{willReadFrequently:true});const pixels=ctx.getImageData(0,0,canvas.width,canvas.height).data;const gray=[];let mean=0,clipped=0;for(let i=0;i<pixels.length;i+=4){const y=.299*pixels[i]+.587*pixels[i+1]+.114*pixels[i+2];gray.push(y);mean+=y;if(y<15||y>245)clipped++;}mean/=gray.length;let sum=0,sum2=0,count=0;const w=canvas.width,h=canvas.height;for(let y=1;y<h-1;y++)for(let x=1;x<w-1;x++){const i=y*w+x,v=4*gray[i]-gray[i-1]-gray[i+1]-gray[i-w]-gray[i+w];sum+=v;sum2+=v*v;count++;}const variance=count?Math.max(0,sum2/count-(sum/count)**2):0;const sharpness=Math.min(1,Math.log1p(variance)/9),exposure=Math.max(0,1-Math.abs(mean-135)/135-clipped/gray.length*.35),resolution=Math.min(1,Math.log2(Math.max(1,width*height))/22);return {sharpness,exposure,resolution,score:sharpness*.5+exposure*.35+resolution*.15};}
async function preparePhoto(file){const url=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(new Error(`${file.name}: this image could not be opened.`));i.src=url;});const scale=Math.min(1,1200/Math.max(img.naturalWidth,img.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const qc=document.createElement('canvas');const qualityScale=160/Math.max(canvas.width,canvas.height);qc.width=Math.max(1,Math.round(canvas.width*qualityScale));qc.height=Math.max(1,Math.round(canvas.height*qualityScale));qc.getContext('2d').drawImage(canvas,0,0,qc.width,qc.height);return {id:uid(),name:file.name,fingerprint:[file.name,file.size,file.lastModified].join(':'),dataUrl:canvas.toDataURL('image/jpeg',.78),width:canvas.width,height:canvas.height,quality:imageQuality(img,qc)};}finally{URL.revokeObjectURL(url);}}
async function addPhotos(files){if(busy||snapshot)return;busy=true;analysisError='';aiMessage='Preparing your photos…';aiProgress=0;render();const errors=[];let added=0;try{for(let i=0;i<files.length;i++){const file=files[i];if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15*1024*1024){errors.push(`${file.name}: use a JPG, PNG or WebP image up to15MB.`);continue;}if(state.photos.length>=MAX_PHOTOS){errors.push(`This space holds up to${MAX_PHOTOS} photos. Save a project backup before starting a new collection.`);break;}const fingerprint=[file.name,file.size,file.lastModified].join(':');if(state.photos.some(p=>p.fingerprint===fingerprint))continue;try{const p=await preparePhoto(file);state.photos.push(p);state.items.push(blankItem([p.id]));added++;}catch(error){errors.push(error.message);}setProgress({message:`Preparing photo ${i+1} of ${files.length}…`,progress:(i+1)/files.length*100});}}finally{busy=false;scheduleSave();render();}if(errors.length)toast(errors.join(' '));if(added)await startSort();}
function setProgress(value){aiMessage=value.message||aiMessage;aiStage=value.stage||aiStage;aiProgress=Math.max(2,Math.min(100,Number(value.progress)||0));const title=document.getElementById('ai-status-title');if(title)title.textContent=aiMessage;const detail=document.getElementById('ai-status-detail');if(detail)detail.textContent=aiStage==='loading'||aiStage==='downloading'?'Downloading the browser model on first use. Photos are not uploaded.':value.total?`Photo ${value.current||0} of ${value.total} · Suggestions need your review.`:'Keep this tab open while the browser works.';const bar=document.getElementById('ai-progress');if(bar)bar.style.width=aiProgress+'%';}
async function startSort(){if(busy||snapshot||!state.photos.length)return;const fixedIds=new Set(state.items.filter(p=>p.approved).flatMap(p=>p.photoIds));let extended=true;while(extended){extended=false;for(const item of state.items){if(item.photoIds.some(id=>fixedIds.has(id)))for(const id of item.photoIds)if(!fixedIds.has(id)){fixedIds.add(id);extended=true;}}}const photos=state.photos.filter(p=>!fixedIds.has(p.id));if(!photos.length){toast('These photos are already used by confirmed items. Review any remaining drafts manually.');return;}busy=true;analysisError='';aiMessage='Loading the browser AI…';aiStage='loading';aiProgress=2;aiController=new AbortController();render();try{if(!window.LetItGoAI)throw new Error('The AI module did not load. Refresh the page to try again.');const result=await window.LetItGoAI.analysePhotos(photos,setProgress,{signal:aiController.signal});if(aiController.signal.aborted)throw new DOMException('Sorting stopped.','AbortError');const updated=new Map(result.photos.map(p=>[p.id,p]));state.photos=state.photos.map(p=>updated.get(p.id)||p);const fixed=state.items.filter(p=>p.approved||p.photoIds.some(id=>fixedIds.has(id)));state.items=[...fixed,...result.groups.map(g=>blankItem(g.photoIds,{id:g.id||uid(),thumbnailId:g.thumbnailId||g.photoIds[0],title:g.title||'Item to identify',category:CATEGORIES.includes(g.category)?g.category:'Other',description:g.title?`A ${g.title.toLowerCase()} ready for another home.`:'',aiSuggested:true,needsReview:g.needsReview!==false,model: '',aiModel:result.model}))];selected.clear();toast('AI suggestions are ready. Check each group and its chosen cover photo.');}catch(error){analysisError=error.name==='AbortError'?'Sorting was stopped. You can review the current photos manually or run AI again.':`The model could not finish: ${error.message} You can retry or review and group items manually.`;}finally{busy=false;aiController=null;aiStage='';scheduleSave();render();}}
function photoStrip(item,editable=false){return `<div class="photo-strip">${item.photoIds.map((id,i)=>{const p=byPhoto(id);return `<button type="button" class="${id===(editingCover||item.thumbnailId)?'active':''}" data-action="${editable?'choose-cover':'view-photo'}" data-photo="${id}" data-item="${item.id}" aria-label="${editable?'Choose':'View'} photo ${i+1}"><img src="${esc(p?.dataUrl||'')}" alt="Item photo ${i+1}">${id===(editingCover||item.thumbnailId)?'<span class="cover-mark">Cover</span>':''}</button>`;}).join('')}</div>`;}
function editItem(id){if(busy||snapshot)return;const item=byItem(id);if(!item)return;editingId=id;editingCover=item.thumbnailId;modal('Your photos. Your final say.',`<form id="review-form"><div class="form-grid"><div><div class="cover-photo"><img id="review-cover" src="${esc(coverPhoto(item)?.dataUrl||'')}" alt="Selected cover photo"><span>Suggested cover · choose any photo below</span></div><div id="review-strip">${photoStrip(item,true)}</div><div class="note">${item.aiSuggested?'AI suggested this group, category and cover. Check that every photo shows the same product.':'Group photos manually and confirm the details you know.'}</div>${item.photoIds.length>1?`<button type="button" class="text-button" data-action="split" data-id="${item.id}">Separate these photos into individual items</button>`:''}<button type="button" class="text-button" data-action="duplicate" data-id="${item.id}">Use these photos for another item</button></div><div><div class="field"><label for="title">Item name</label><input id="title" name="title" value="${esc(item.title)}" maxlength="120" required></div><div class="field-row"><div class="field"><label for="item-category">Category</label><select id="item-category" name="category">${CATEGORIES.map(c=>`<option${item.category===c?' selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label for="condition">Condition</label><select id="condition" name="condition">${CONDITIONS.map(c=>`<option${item.condition===c?' selected':''}>${c}</option>`).join('')}</select></div></div><div class="field-row"><div class="field"><label for="brand">Brand (optional)</label><input id="brand" name="brand" value="${esc(item.brand)}" maxlength="100" placeholder="Unknown is fine"></div><div class="field"><label for="model">Model (optional)</label><input id="model" name="model" value="${esc(item.model)}" maxlength="100"></div></div><div class="field-row"><div class="field"><label for="age">Age (optional)</label><input id="age" name="age" value="${esc(item.age)}" maxlength="100" placeholder="e.g. About 2 years"></div><div class="field"><label for="price">Asking price (₹, optional)</label><input id="price" name="price" type="number" min="0" max="10000000" step="0.01" value="${item.price??''}" placeholder="Leave blank to ask"><small>0 means free.</small></div></div><div class="field"><label for="description">Description & known wear</label><textarea id="description" name="description" maxlength="3000" placeholder="Add accessories, working condition and any marks…">${esc(item.description)}</textarea></div><div class="field"><label for="product-url">Product reference (optional)</label><input id="product-url" name="productUrl" type="url" value="${esc(item.productUrl)}" maxlength="1000" placeholder="https://…"></div><div class="field"><label for="status">Availability</label><select id="status" name="status">${[['available','Available'],['reserved','Reserved'],['sold','Rehomed'],['draft','Keep private']].map(([key,label])=>`<option value="${key}"${item.status===key?' selected':''}>${label}</option>`).join('')}</select></div></div></div><label class="checkline"><input name="confirmed" type="checkbox" required>I checked the photo group, cover and details. I approve this item for my catalogue, unless I chose “Keep private”.</label><div class="error" id="review-error" role="alert"></div><div class="modal-actions"><button class="text-button danger" type="button" data-action="remove-one" data-id="${item.id}">Remove item</button><button class="secondary" type="button" data-action="close">Cancel</button><button class="primary" type="submit">${icon('check')}Confirm item</button></div></form>`);document.getElementById('review-form').onsubmit=saveReview;}
function safeProductUrl(raw){if(!raw)return '';let u;try{u=new URL(raw);}catch{throw new Error('Use a complete https:// product reference or leave it blank.');}if(u.protocol!=='https:'||u.username||u.password)throw new Error('Product references must use https:// without login details.');return u.href;}
function saveReview(e){e.preventDefault();const item=byItem(editingId);if(!item)return;const f=Object.fromEntries(new FormData(e.target));try{if(!f.confirmed||!String(f.title).trim())throw new Error('Check the details, give this item a name, and confirm it.');const amount=f.price===''?null:Number(f.price);if(amount!==null&&(!Number.isFinite(amount)||amount<0||amount>10000000||Math.abs(Math.round(amount*100)-amount*100)>1e-7))throw new Error('Use a valid price with up to two decimal places, or leave it blank.');if(!CATEGORIES.includes(f.category)||!CONDITIONS.includes(f.condition))throw new Error('Choose a category and condition from the list.');Object.assign(item,{title:String(f.title).trim(),category:f.category,condition:f.condition,brand:String(f.brand||'').trim(),model:String(f.model||'').trim(),age:String(f.age||'').trim(),description:String(f.description||'').trim(),price:amount,status:f.status,productUrl:safeProductUrl(f.productUrl),thumbnailId:item.photoIds.includes(editingCover)?editingCover:item.photoIds[0],approved:true,confirmedAt:new Date().toISOString()});closeModal();scheduleSave();render();toast('Item confirmed. Your catalogue is taking shape.');}catch(error){document.getElementById('review-error').textContent=error.message;}}
function details(id){const item=byItem(id);if(!item||!item.approved||item.status==='draft')return;modal(item.title,`<div class="form-grid"><div><div class="cover-photo viewer-photo"><img id="detail-cover" src="${esc(coverPhoto(item)?.dataUrl||'')}" alt="${esc(item.title)}"></div>${photoStrip(item)}</div><div><div class="eyebrow">${esc(item.category)}</div><h3 class="serif detail-title">${esc(item.title)}</h3><strong>${price(item.price)}</strong><div style="margin-top:14px"><span class="status-pill">${esc(item.status==='reserved'?'Reserved':item.status==='sold'?'Rehomed':item.condition)}</span></div><p class="detail-description" style="margin-top:18px">${esc(item.description)}</p><dl class="facts"><div><dt>Brand</dt><dd>${esc(item.brand||'Not specified')}</dd></div><div><dt>Model</dt><dd>${esc(item.model||'Not specified')}</dd></div><div><dt>Age</dt><dd>${esc(item.age||'Not specified')}</dd></div><div><dt>Photos</dt><dd>${item.photoIds.length}</dd></div></dl>${item.productUrl?`<a class="secondary" href="${esc(item.productUrl)}" target="_blank" rel="noopener noreferrer">Product reference</a>`:''}<p class="local-note" style="margin-top:22px">Details provided and confirmed by the owner. Availability may change after export.</p></div></div>`);}
function mergeSelected(){if(busy||snapshot)return;const chosen=state.items.filter(p=>selected.has(p.id));if(chosen.length<2)return;const ids=[...new Set(chosen.flatMap(p=>p.photoIds))];if(ids.length>MAX_PER_ITEM){toast(`Keep each product group to ${MAX_PER_ITEM} photos or fewer.`);return;}const first=chosen[0],cover=window.LetItGoAI?.chooseThumbnail?window.LetItGoAI.chooseThumbnail(ids.map(byPhoto)):ids[0];const merged={...first,id:uid(),photoIds:ids,thumbnailId:typeof cover==='string'?cover:cover?.id||first.thumbnailId,approved:false,needsReview:true,aiSuggested:false};state.items=state.items.filter(p=>!selected.has(p.id));state.items.unshift(merged);selected.clear();scheduleSave();render();toast('Photos grouped. Review the new item before sharing.');}
function splitItem(id){if(busy||snapshot)return;const item=byItem(id);if(!item||item.photoIds.length<2)return;const replacements=item.photoIds.map(photoId=>{const p=byPhoto(photoId);return blankItem([photoId],{title:p.titleSuggested||'Item to identify',category:CATEGORIES.includes(p.category)?p.category:'Other',aiSuggested:!!p.embedding});});state.items.splice(state.items.indexOf(item),1,...replacements);selected.delete(id);closeModal();scheduleSave();render();toast('Photos separated. Select and group the ones that belong together.');}
function prunePhotos(){const used=new Set(state.items.flatMap(p=>p.photoIds));state.photos=state.photos.filter(p=>used.has(p.id));}
function removeSelected(){if(busy||snapshot)return;const count=state.items.filter(p=>selected.has(p.id)).length;if(!count)return;modal('Remove selected items?',`<p>Remove ${count} ${count===1?'item':'items'} from this device’s collection? Previously exported PDFs and catalogues keep their copies.</p><div class="modal-actions"><button class="secondary" data-action="close">Keep items</button><button class="primary" data-action="remove-confirmed">Remove selected items</button></div>`,true);}
function catalogueSettings(){modal('Introduce your collection.',`<form id="catalogue-form"><div class="field"><label for="catalogue-title">Catalogue title</label><input id="catalogue-title" name="title" value="${esc(state.catalogue.title)}" maxlength="120" required></div><div class="field"><label for="owner-name">Name to display (optional)</label><input id="owner-name" name="ownerName" value="${esc(state.catalogue.ownerName)}" maxlength="100"></div><div class="field"><label for="catalogue-description">A short introduction</label><textarea id="catalogue-description" name="description" maxlength="1000">${esc(state.catalogue.description)}</textarea></div><div class="modal-actions"><button class="secondary" type="button" data-action="close">Cancel</button><button class="primary" type="submit">Save introduction</button></div></form>`,true);document.getElementById('catalogue-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));state.catalogue={title:String(f.title).trim(),ownerName:String(f.ownerName||'').trim(),description:String(f.description||'').trim()};scheduleSave();closeModal();render();};}
function exportOptions(){return {catalogueTitle:state.catalogue.title,sellerName:state.catalogue.ownerName,description:state.catalogue.description,shareUrl:lastShareUrl};}
function shareModal(){window.LetItGoHosted?.reset();if(!approvedItems().length){toast('Review and confirm at least one item first.');return;}modal('A collection worth passing around.',`<p class="muted">Only confirmed, non-private items are included. Choose a category or the complete catalogue.</p><div class="field"><label for="export-category">What would you like to share?</label><select id="export-category"><option>All categories</option>${CATEGORIES.filter(c=>approvedItems().some(p=>p.category===c)).map(c=>`<option>${c}</option>`).join('')}</select></div><div class="share-list"><section class="share-option">${icon('book')}<div><h3>A PDF to send anywhere</h3><p>Photos, prices and confirmed details in a printable catalogue.</p><button class="primary" data-action="pdf">Download PDF</button></div></section><section class="share-option">${icon('file')}<div><h3>A complete HTML catalogue</h3><p>A single file with photos, category filters and galleries. Send it as a file or host it on your own site.</p><button class="secondary" data-action="html">Download HTML catalogue</button></div></section><section class="share-option">${icon('link')}<div><h3>A short catalogue link</h3><p>${window.LetItGoHosted?.ready()?'Publish the selected confirmed photos without an account. The link expires after30days; keep the owner link private if you want to delete it sooner.':'The no-login storage option is prepared but not connected yet. Add your storage URL and public visitor-check key in config.js after deployment.'}</p><div id="storage-challenge"></div><button class="primary" data-action="publish-hosted" ${!window.LetItGoHosted?.ready()?'disabled':''}>Publish & get a link</button><div id="hosted-result" role="status"></div></div></section><section class="share-option">${icon('link')}<div><h3>A self-contained link</h3><p>Fits very small photo collections only. Larger catalogues need a storage service for a short link. This link is a snapshot and cannot be revoked.</p><button class="secondary" data-action="create-link">Try creating a link</button><div id="link-result" role="status"></div></div></section></div><p class="local-note" style="margin:20px 0 0">Sharing includes your selected photos and visible details. Exported copies stay with their recipients.</p>`,true);if(window.LetItGoHosted?.ready())window.LetItGoHosted.mount(document.getElementById('storage-challenge')).catch(e=>{const el=document.getElementById('hosted-result');if(el)el.textContent=e.message;});}
function exportCategory(){return document.getElementById('export-category')?.value||'All categories';}
function selectedExports(){const c=exportCategory();return exportItems().filter(p=>p.approved&&p.status!=='draft'&&(c==='All categories'||p.category===c));}
async function pdfExport(button){button.disabled=true;const old=button.textContent;button.textContent='Preparing PDF…';try{if(!window.LetItGoPdf)throw new Error('PDF export is not ready. Refresh and try again.');await ensurePortablePhotos();await window.LetItGoPdf.download(exportItems(),exportCategory(),exportOptions());toast('PDF downloaded. Attach it in your preferred app.');}catch(error){toast(error.message);}finally{button.disabled=false;button.textContent=old;}}
async function createLink(button){button.disabled=true;const result=document.getElementById('link-result');result.textContent='Preparing your link…';try{await ensurePortablePhotos();const data=await window.LetItGoShare.encodeLink(state.catalogue,selectedExports(),new URL(location.pathname,location.origin).href);const url=typeof data==='string'?data:data.url;lastShareUrl=url;result.innerHTML=`<div class="link-field" style="margin-top:12px"><input readonly id="generated-link" value="${esc(url)}" aria-label="Shareable catalogue link"><button class="secondary" data-action="copy-link">Copy</button></div><p style="margin:9px 0 0">Anyone with this link can view its included photos and details.</p>`;}catch(error){result.innerHTML=`<div class="note warning" style="margin-top:12px">${error.code==='LINK_TOO_LARGE'?'These photos are too large to fit safely in a link. Download the complete HTML catalogue or PDF instead. A short link for a collection this size requires hosted storage.':esc(error.message)}</div>`;}finally{button.disabled=false;}}
async function copyLink(){if(!lastShareUrl)return;try{await navigator.clipboard.writeText(lastShareUrl);toast('Catalogue link copied.');}catch{document.getElementById('generated-link')?.select();toast('Select and copy the full link shown.');}}
function loadImported(data){if(!data||!Array.isArray(data.items))throw new Error('This is not a catalogue project.');const photos=[],items=[],seen=new Map();for(const item of data.items){const sources=Array.isArray(item.photos)&&item.photos.length?item.photos:(item.images||[]).map((dataUrl,i)=>({id:item.id+'-'+i,dataUrl}));const ids=[];for(const source of sources){const image=typeof source==='string'?source:source.dataUrl||source.dataURL||source.url;if(!image)continue;let id=seen.get(image);if(!id){id=uid();seen.set(image,id);photos.push({id,dataUrl:image,width:source.width||0,height:source.height||0,quality:source.quality||{score:.5},name:'Imported photo'});}ids.push(id);}if(!ids.length&&item.image){const id=uid();photos.push({id,dataUrl:item.image,width:0,height:0,quality:{score:.5},name:'Imported photo'});ids.push(id);}if(ids.length)items.push({...blankItem(ids),...item,id:uid(),photoIds:ids,thumbnailId:ids[0],approved:item.approved===true||item.confirmed===true});}if(photos.length>200)throw new Error('This project has too many photos.');state={version:1,catalogue:{title:data.catalogue?.title||data.catalogue?.catalogueTitle||'A Let It Go! catalogue',ownerName:data.catalogue?.ownerName||data.catalogue?.sellerName||'',description:data.catalogue?.description||''},photos,items};selected.clear();}
async function importProject(file){if(!file||busy||snapshot)return;try{const data=await window.LetItGoShare.readProject(file);loadImported(data);lastShareUrl='';scheduleSave();render();toast('Project opened. Review items before exporting.');}catch(error){toast(error.message);}}
async function loadSamples(){if(busy||snapshot)return;try{busy=true;const image=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src='assets/products.png';});const files=[];for(let i=0;i<3;i++){for(let view=0;view<2;view++){const canvas=document.createElement('canvas');canvas.width=512;canvas.height=512;const ctx=canvas.getContext('2d');ctx.fillStyle='#eeeade';ctx.fillRect(0,0,512,512);const margin=view?12:0;ctx.drawImage(image,i*image.width/3,0,image.width/3,image.height/2,margin,margin,512-2*margin,512-2*margin);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.85));files.push(new File([blob],`sample-item-${i+1}-view-${view+1}.jpg`,{type:'image/jpeg',lastModified:Date.now()+i*2+view}));}}busy=false;await addPhotos(files);}catch{busy=false;toast('Sample photos could not be loaded. Add your own photos to begin.');render();}}
async function doAction(e){const button=e.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action,id=button.dataset.id;e.preventDefault();try{switch(action){case'view':if(busy){toast('Stop AI sorting before changing views.');return;}view=button.dataset.view;query='';category='All categories';reviewFilter='all';selected.clear();closeModal();render();break;case'sort':await startSort();break;case'cancel-ai':aiController?.abort();break;case'review':editItem(id);break;case'details':details(id);break;case'close':closeModal();break;case'choose-cover':{editingCover=button.dataset.photo;const p=byPhoto(editingCover);if(p)document.getElementById('review-cover').src=p.dataUrl;document.getElementById('review-strip').innerHTML=photoStrip(byItem(editingId),true);break;}case'view-photo':{const p=byPhoto(button.dataset.photo);if(p)document.getElementById('detail-cover').src=p.dataUrl;break;}case'merge':mergeSelected();break;case'split':splitItem(id);break;case'duplicate':{const p=byItem(id);if(!p||snapshot)break;const copy={...p,id:uid(),photoIds:[...p.photoIds],approved:false,aiSuggested:false,title:'Another item to identify'};state.items.push(copy);scheduleSave();closeModal();render();toast('Another item added using the same photos. Review its details separately.');break;}case'remove-selected':removeSelected();break;case'remove-one':selected=new Set([id]);removeSelected();break;case'remove-confirmed':state.items=state.items.filter(p=>!selected.has(p.id));prunePhotos();selected.clear();closeModal();scheduleSave();render();break;case'catalogue-settings':catalogueSettings();break;case'share':shareModal();break;case'pdf':await pdfExport(button);break;case'html':await ensurePortablePhotos();await window.LetItGoShare.downloadHtml(state.catalogue,selectedExports());toast('HTML catalogue downloaded with its photos.');break;case'create-link':await createLink(button);break;case'publish-hosted':await publishHosted(button);break;case'copy-owner':await copyValue(button.dataset.url,'Private owner link copied. Keep it separate from the catalogue link.');break;case'delete-hosted':await deleteHosted(button);break;case'copy-link':await copyLink();break;case'backup':await window.LetItGoShare.downloadProject(state.catalogue,exportItems());toast('Project backup downloaded.');break;case'import':document.getElementById('project-input')?.click();break;case'sample':await loadSamples();break;}}catch(error){toast(error.message||'Something went wrong. Please try again.');}}
document.addEventListener('click',doAction);
document.addEventListener('change',e=>{if(e.target.dataset?.select){e.target.checked?selected.add(e.target.dataset.select):selected.delete(e.target.dataset.select);const merge=document.querySelector('[data-action="merge"]'),remove=document.querySelector('[data-action="remove-selected"]');if(merge)merge.disabled=selected.size<2;if(remove)remove.disabled=!selected.size;}if(e.target.id==='export-category'){lastShareUrl='';const result=document.getElementById('link-result');if(result)result.innerHTML='';}if(e.target.id==='category'){category=e.target.value;render();}if(e.target.id==='review-filter'){reviewFilter=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id!=='search')return;query=e.target.value;const start=e.target.selectionStart;render();const input=document.getElementById('search');input?.focus();try{input?.setSelectionRange(start,start);}catch{}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();const dialog=document.querySelector('[role="dialog"]');if(e.key==='Tab'&&dialog){const nodes=[...dialog.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select,textarea')].filter(el=>el.getClientRects().length);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('beforeunload',e=>{if(busy||saveLabel.startsWith('Not saved')||saveLabel.startsWith('Saving')){e.preventDefault();e.returnValue='';}});
window.LetItGoApp={blankItem,exportItems,approvedItems,filterItems,safeProductUrl,loadImported};
function loadHosted(data){if(!data||!Array.isArray(data.items)||!Array.isArray(data.photos)||data.items.length>50||data.photos.length>40)throw new Error('This hosted catalogue is invalid.');const service=window.LetItGoHosted.config();const photoIds=new Set();const photos=data.photos.map(p=>{const url=new URL(p.dataUrl);if(url.origin!==new URL(service.base).origin||!url.pathname.includes('/v1/catalogues/')||!url.pathname.includes('/photos/'))throw new Error('This catalogue contains an invalid photo address.');photoIds.add(p.id);return {id:p.id,dataUrl:url.href,width:p.width||0,height:p.height||0,quality:{score:.5}};});const items=data.items.filter(p=>p.approved===true&&p.status!=='draft').map(p=>{if(!Array.isArray(p.photoIds)||p.photoIds.some(id=>!photoIds.has(id)))throw new Error('A catalogue photo is missing.');return {...p,productUrl:safeProductUrl(p.productUrl||''),thumbnailId:p.photoIds.includes(p.thumbnailId)?p.thumbnailId:p.photoIds[0]};});state={version:1,catalogue:{title:data.catalogue.title||'A Let It Go! catalogue',ownerName:data.catalogue.ownerName||'',description:data.catalogue.description||''},photos,items};}
async function copyValue(text,message='Link copied.'){try{await navigator.clipboard.writeText(text);toast(message);}catch{toast('Select and copy the complete link shown.');}}
async function publishHosted(button){const result=document.getElementById('hosted-result');button.disabled=true;try{if(!window.LetItGoHosted.ready())throw new Error('Configure the storage service before publishing.');const token=window.LetItGoHosted.token();await ensurePortablePhotos();result.textContent='Preparing your selected catalogue…';const cat=exportCategory(),chosen=state.items.filter(p=>p.approved&&p.status!=='draft'&&(cat==='All categories'||p.category===cat));const saved=await window.LetItGoHosted.publish(state.catalogue,chosen,state.photos,token,text=>result.textContent=text);const url=new URL(location.pathname,location.origin);url.searchParams.set('catalogue',saved.id);const owner=new URL(location.pathname,location.origin);owner.searchParams.set('manage',saved.id);owner.hash='token='+saved.ownerToken;lastShareUrl=url.href;if(!snapshot){state.sharedLinks=state.sharedLinks||[];state.sharedLinks.push({id:saved.id,url:url.href,ownerUrl:owner.href,expiresAt:saved.expiresAt});await saveProject();}result.innerHTML=`<div class="field" style="margin-top:16px"><label>Catalogue link — share this</label><input readonly value="${esc(url.href)}"></div><button class="secondary" data-action="copy-link">Copy catalogue link</button><div class="field" style="margin-top:16px"><label>Owner link — keep this private</label><input readonly value="${esc(owner.href)}"><small>Anyone with the owner link can delete this shared catalogue. Save it privately.</small></div><button class="text-button" data-action="copy-owner" data-url="${esc(owner.href)}">Copy private owner link</button><p>Expires ${esc(new Date(saved.expiresAt).toLocaleDateString('en-IN'))}. This is a snapshot; publish again for later changes.</p>`;window.LetItGoHosted.reset();}catch(error){result.textContent=error.message;try{window.LetItGoHosted.reset();await window.LetItGoHosted.mount(document.getElementById('storage-challenge'));}catch{}}finally{button.disabled=false;}}
function ownerManagement(id,ownerToken){modal('Manage this shared catalogue',`<p>This private owner link can remove the shared catalogue and its stored photos. It does not delete previously downloaded PDF or HTML copies.</p><label class="checkline"><input id="delete-hosted-check" type="checkbox">I want to delete this shared catalogue and disable its public link.</label><div class="error" id="delete-hosted-error" role="alert"></div><div class="modal-actions"><a class="secondary" href="${esc(location.pathname)}">Back to Let It Go!</a><button class="primary" data-action="delete-hosted" data-id="${esc(id)}" data-token="${esc(ownerToken||'')}">Delete shared catalogue</button></div>`,true);}
async function deleteHosted(button){const error=document.getElementById('delete-hosted-error');if(!document.getElementById('delete-hosted-check').checked){error.textContent='Confirm that you want to delete this shared catalogue.';return;}button.disabled=true;try{await window.LetItGoHosted.remove(button.dataset.id,button.dataset.token);modal('Shared catalogue deleted',`<p>The catalogue link and stored photos have been removed. Downloaded copies remain with their recipients.</p><div class="modal-actions"><a class="primary" href="${esc(location.pathname)}">Open Let It Go!</a></div>`,true);}catch(e){error.textContent=e.message;button.disabled=false;}}


async function ensurePortablePhotos(){const pending=state.photos.filter(p=>/^https:\/\//i.test(p.dataUrl));if(!pending.length)return;const replacements=[];for(const p of pending){const response=await fetch(p.dataUrl,{credentials:'omit',mode:'cors',referrerPolicy:'no-referrer'});if(!response.ok)throw new Error('A shared photo is unavailable. The catalogue may have expired or been deleted.');const blob=await response.blob();if(!['image/jpeg','image/png','image/webp'].includes(blob.type)||blob.size>1024*1024)throw new Error('A shared photo has an unsupported format or size.');const dataUrl=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('A shared photo could not be prepared for export.'));r.readAsDataURL(blob);});replacements.push([p,dataUrl]);}for(const [p,dataUrl]of replacements)p.dataUrl=dataUrl;}
initialise();
